update pms_work_log
   set status = 'CONFIRMED', confirmed_at = now(), row_ver = row_ver + 1, updated_at = now(), updated_by = #{by}
 where user_id = #{userId} and work_day = #{day} and status = 'DRAFT'

update pms_work_log
   set status = 'DRAFT', reopen_reason = #{reason}, row_ver = row_ver + 1, updated_at = now(), updated_by = #{by}
 where user_id = #{userId} and work_day = #{day} and status = 'CONFIRMED'

mapper.select:
select 


 order by case i.severity when 'HIGH' then 0 when 'MID' then 1 else 2 end, i.due_date nulls last, i.issue_id desc
 limit #{limit}

mapper.update:
update pms_issue
   set task_id = #{f.taskId}, title = #{f.title}, detail = #{f.detail}, severity = #{f.severity},
       owner_user_id = #{f.ownerUserId}, due_date = #{f.dueDate}, obj_type = #{f.objType}, obj_id = #{f.objId},
       issue_type = #{f.issueType}, row_ver = row_ver + 1, updated_at = now(), updated_by = #{by}
 where issue_id = #{id} and row_ver = #{rowVer}

update pms_issue
   set status = #{status}, resolution = #{resolution}, resolved_on = #{resolvedOn}, close_kind = #{closeKind},
       row_ver = row_ver + 1, updated_at = now(), updated_by = #{by}
 where issue_id = #{id} and row_ver = #{rowVer}

mapper.select:
select i.status as issue_status, p.status as proj_status
  from pms_issue i join pms_project p on p.proj_id = i.proj_id
 where i.issue_id = #{id}


   select 'ITEM' as obj_type, item_id as obj_id, item_cd as obj_cd, item_nm as obj_nm from mst_item where item_cd = #{objCd}
   select 'CUST' as obj_type, cust_id as obj_id, cust_cd as obj_cd, cust_nm as obj_nm from mst_cust where cust_cd = #{objCd}
   select 'EQUIP' as obj_type, equip_id as obj_id, equip_cd as obj_cd, equip_nm as obj_nm from mst_equip where equip_cd = #{objCd}
   select 'ASSET' as obj_type, asset_id as obj_id, asset_cd as obj_cd, asset_nm as obj_nm from mst_phys_asset where asset_cd = #{objCd}

limit 2
